// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkItemForecast) predicate.WorkItemForecast {
	return predicate.WorkItemForecast(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkItemForecast) predicate.WorkItemForecast {
	return predicate.WorkItemForecast(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkItemForecast) predicate.WorkItemForecast {
	return predicate.WorkItemForecast(sql.NotPredicates(p))
}
